class ESimManager_GetAvailableEuiccs_ProxyToResponder : public ::mojo::internal::ProxyToResponder {
 public:
  static ESimManager::GetAvailableEuiccsCallback CreateCallback(
      ::mojo::Message& message,
      std::unique_ptr<mojo::MessageReceiverWithStatus> responder) {
    std::unique_ptr<ESimManager_GetAvailableEuiccs_ProxyToResponder> proxy(
        new ESimManager_GetAvailableEuiccs_ProxyToResponder(
            message, std::move(responder)));
    return base::BindOnce(&ESimManager_GetAvailableEuiccs_ProxyToResponder::Run,
                          std::move(proxy));
  }

  ~ESimManager_GetAvailableEuiccs_ProxyToResponder() {
#if DCHECK_IS_ON()
    if (responder_) {
      // If we're being destroyed without being run, we want to ensure the
      // binding endpoint has been closed. This checks for that asynchronously.
      // We pass a bound generated callback to handle the response so that any
      // resulting DCHECK stack will have useful interface type information.
      // Instantiate a ScopedFizzleBlockShutdownTasks to allow this request to
      // fizzle if this happens after shutdown and the endpoint is bound to a
      // BLOCK_SHUTDOWN sequence.
      base::ThreadPoolInstance::ScopedFizzleBlockShutdownTasks fizzler;
      responder_->IsConnectedAsync(base::BindOnce(&OnIsConnectedComplete));
    }
#endif
  }

 private:
  ESimManager_GetAvailableEuiccs_ProxyToResponder(
      ::mojo::Message& message,
      std::unique_ptr<mojo::MessageReceiverWithStatus> responder)
      : ::mojo::internal::ProxyToResponder(message, std::move(responder)) {
  }

#if DCHECK_IS_ON()
  static void OnIsConnectedComplete(bool connected) {
    DCHECK(!connected)
        << "ESimManager::GetAvailableEuiccsCallback was destroyed without "
        << "first either being run or its corresponding binding being closed. "
        << "It is an error to drop response callbacks which still correspond "
        << "to an open interface pipe.";
  }
#endif

  void Run(
      std::vector<::mojo::PendingRemote<Euicc>> in_euiccs);
};

bool ESimManager_GetAvailableEuiccs_ForwardToCallback::Accept(
    mojo::Message* message) {

  DCHECK(message->is_serialized());
  internal::ESimManager_GetAvailableEuiccs_ResponseParams_Data* params =
      reinterpret_cast<
          internal::ESimManager_GetAvailableEuiccs_ResponseParams_Data*>(
              message->mutable_payload());
  
  bool success = true;
  std::vector<::mojo::PendingRemote<Euicc>> p_euiccs{};
  ESimManager_GetAvailableEuiccs_ResponseParamsDataView input_data_view(params, message);
  
  if (success && !input_data_view.ReadEuiccs(&p_euiccs))
    success = false;
  if (!success) {
    ReportValidationErrorForMessage(
        message,
        mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
        ESimManager::Name_, 1, true);
    return false;
  }
  if (!callback_.is_null())
    std::move(callback_).Run(
std::move(p_euiccs));
  return true;
}

void ESimManager_GetAvailableEuiccs_ProxyToResponder::Run(
    std::vector<::mojo::PendingRemote<Euicc>> in_euiccs) {
#if BUILDFLAG(MOJO_TRACE_ENABLED)
  TRACE_EVENT1(
    "mojom", "Send reply ash::cellular_setup::mojom::ESimManager::GetAvailableEuiccs", "async_response_parameters",
    [&](perfetto::TracedValue context){
      auto dict = std::move(context).WriteDictionary();
      perfetto::WriteIntoTracedValueWithFallback(
           dict.AddItem("euiccs"), in_euiccs,
                        "<value of type std::vector<::mojo::PendingRemote<Euicc>>>");
   });
#endif
  
  const uint32_t kFlags = mojo::Message::kFlagIsResponse |
      ((is_sync_) ? mojo::Message::kFlagIsSync : 0) |
      ((true) ? 0 : mojo::Message::kFlagNoInterrupt);
  
  mojo::Message message(
      internal::kESimManager_GetAvailableEuiccs_Name, kFlags, 0, 0, nullptr);
  mojo::internal::MessageFragment<
      ::ash::cellular_setup::mojom::internal::ESimManager_GetAvailableEuiccs_ResponseParams_Data> params(
          message);
  params.Allocate();
  mojo::internal::MessageFragment<
      typename decltype(params->euiccs)::BaseType>
      euiccs_fragment(params.message());
  constexpr const mojo::internal::ContainerValidateParams& euiccs_validate_params =
      mojo::internal::GetArrayValidator<0, false, nullptr>();
  mojo::internal::Serialize<mojo::ArrayDataView<mojo::InterfacePtrDataView<::ash::cellular_setup::mojom::EuiccInterfaceBase>>>(
      in_euiccs, euiccs_fragment, &euiccs_validate_params);
  params->euiccs.Set(
      euiccs_fragment.is_null() ? nullptr : euiccs_fragment.data());
  MOJO_INTERNAL_DLOG_SERIALIZATION_WARNING(
      params->euiccs.is_null(),
      mojo::internal::VALIDATION_ERROR_UNEXPECTED_NULL_POINTER,
      "null euiccs in ");

#if defined(ENABLE_IPC_FUZZER)
  message.set_interface_name(ESimManager::Name_);
  message.set_method_name("GetAvailableEuiccs");
#endif

  message.set_request_id(request_id_);
  message.set_trace_nonce(trace_nonce_);
  ::mojo::internal::SendMojoMessage(*responder_, message);
  // SendMojoMessage() fails silently if the responder connection is closed,
  // or if the message is malformed.
  //
  // TODO(darin): If Accept() returns false due to a malformed message, that
  // may be good reason to close the connection. However, we don't have a
  // way to do that from here. We should add a way.
  responder_ = nullptr;
}

