bool StructTraits<::ash::cellular_setup::mojom::ESimProfileProperties::DataView, ::ash::cellular_setup::mojom::ESimProfilePropertiesPtr>::Read(
    ::ash::cellular_setup::mojom::ESimProfileProperties::DataView input,
    ::ash::cellular_setup::mojom::ESimProfilePropertiesPtr* output) {
  bool success = true;
  ::ash::cellular_setup::mojom::ESimProfilePropertiesPtr result(::ash::cellular_setup::mojom::ESimProfileProperties::New());
  
      if (success && !input.ReadEid(&result->eid))
        success = false;
      if (success && !input.ReadIccid(&result->iccid))
        success = false;
      if (success && !input.ReadName(&result->name))
        success = false;
      if (success && !input.ReadNickname(&result->nickname))
        success = false;
      if (success && !input.ReadServiceProvider(&result->service_provider))
        success = false;
      if (success && !input.ReadState(&result->state))
        success = false;
      if (success && !input.ReadActivationCode(&result->activation_code))
        success = false;
  *output = std::move(result);
  return success;
}


