bool StructTraits<::ash::cellular_setup::mojom::QRCode::DataView, ::ash::cellular_setup::mojom::QRCodePtr>::Read(
    ::ash::cellular_setup::mojom::QRCode::DataView input,
    ::ash::cellular_setup::mojom::QRCodePtr* output) {
  bool success = true;
  ::ash::cellular_setup::mojom::QRCodePtr result(::ash::cellular_setup::mojom::QRCode::New());
  
      if (success)
        result->size = input.size();
      if (success && !input.ReadData(&result->data))
        success = false;
  *output = std::move(result);
  return success;
}

